// 初始化 base case
// dp[状态1][状态2][...] = base

// 进行状态转移
// for 状态1 in 状态1的所有取值：
//     for 状态2 in 状态2的所有取值：
//         for ...
//             dp[状态1][状态2][...] = 求最值(选择1，选择2...)
// 例如本题的凑零钱：dp[n] = min(dp[n], 1 + dp[n-coin])

func coinChange(coins []int, amount int) int {
	// 备忘录
	memo := map[int]int{}
	var dp func(n int) int
	dp = func(n int) int {
		// 查备忘录，避免重复计算
		if v, ok := memo[n]; ok {
			return v
		}
		// base case
		if n == 0 {
			return 0
		}
		if n < 0 {
			return -1
		}
		res := int(^uint(0) >> 1) // 相当于 float('INF')
		for _, coin := range coins {
			subproblem := dp(n - coin)
			if subproblem == -1 {
				continue
			}
			if 1+subproblem < res {
				res = 1 + subproblem
			}
		}
		// 记入备忘录
		if res == int(^uint(0)>>1) {
			memo[n] = -1
		} else {
			memo[n] = res
		}
		return memo[n]
	}
	return dp(amount)
}

