func coinChange(coins []int, amount int) int {
	memo := map[int]int{}
	var dp func(rem int) int
	dp = func(rem int) int {
		if rem < 0 {
			return -1
		}
		if rem == 0 {
			return 0
		}
		if v, ok := memo[rem]; ok {
			return v
		}
		mini := int(1e9)
		for _, coin := range coins {
			res := dp(rem - coin)
			if res >= 0 && res < mini {
				mini = res + 1
			}
		}
		if mini < int(1e9) {
			memo[rem] = mini
		} else {
			memo[rem] = -1
		}
		return memo[rem]
	}
	if amount < 1 {
		return 0
	}
	return dp(amount)
}

func coinChange(coins []int, amount int) int {
	dp := make([]int, amount+1)
	for i := range dp {
		dp[i] = int(^uint(0) >> 1) // 相当于 float('inf')
	}
	dp[0] = 0
	for _, coin := range coins {
		for x := coin; x <= amount; x++ {
			if dp[x-coin]+1 < dp[x] {
				dp[x] = dp[x-coin] + 1
			}
		}
	}
	if dp[amount] == int(^uint(0)>>1) {
		return -1
	}
	return dp[amount]
}
